<script setup lang="ts">
import{computed,onMounted,ref}from'vue';import{stage10Api}from'@/api/stage10';const question=ref('最近7天按来源统计采集内容'),result=ref<any>(),history=ref<any[]>([]),cap=ref<any>(),busy=ref(false);const max=computed(()=>Math.max(...(result.value?.series||[]).map((x:any)=>x.value),1));async function ask(){busy.value=true;try{result.value=await stage10Api.biQuery(question.value);history.value=await stage10Api.biHistory()}finally{busy.value=false}}onMounted(async()=>{[cap.value,history.value]=await Promise.all([stage10Api.biCapabilities(),stage10Api.biHistory()])})
